def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def pick_nearest(pos, items):
        best = None
        best_score = None
        for item in items:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            p = [item[0], item[1]]
            score = dist(pos, p)
            if best is None or score < best_score:
                best = p
                best_score = score
        return best

    def center_target(w, h):
        return [w // 2 if w else 0, h // 2 if h else 0]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [sx, sy])
    self_pos = [sx, sy]
    opp_pos = [ox, oy]
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        if w and h:
            target = max(corners, key=lambda c: dist(c, opp_pos))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        best = pick_nearest(self_pos, targets)
        if best is not None:
            return step_toward(self_pos, best)
        return step_toward(self_pos, center_target(w, h))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = pick_nearest(self_pos, resources)
    if best is not None:
        move = step_toward(self_pos, best)
        if dist(self_pos, opp_pos) <= 2 and dist(best, opp_pos) < dist(self_pos, opp_pos):
            away = step_away(self_pos, opp_pos)
            if away != [0, 0]:
                return away
        return move

    if dist(self_pos, opp_pos) > 0:
        return step_away(self_pos, opp_pos)
    return [0, 0]

